import { CommonModule } from '@angular/common';
import { AfterViewChecked, ChangeDetectionStrategy, ChangeDetectorRef, Component, ElementRef, EventEmitter, Input, OnChanges, OnInit, Output, SimpleChanges, ViewChild } from '@angular/core';
import { MatTooltipModule } from '@angular/material/tooltip';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { fileUploadMDL, replaceMdl, uploadAppliedFilters, uploadMasterMDL, uploadingFilesMDL } from '../../../interfaces/upload.interface';
import { BytesPipe } from '../../../../shared/pips/bytes/bytes.pipe';
import { environment } from '../../../../../environments/environment';
import { UploadManagementService } from '../../../services/upload/upload-management/upload-management.service';
import { MatPaginator, MatPaginatorModule } from '@angular/material/paginator';
import { MatSort, MatSortModule } from '@angular/material/sort';
import { MatTable, MatTableDataSource, MatTableModule } from '@angular/material/table';
import { MatInputModule } from '@angular/material/input';
import { SelectionModel } from '@angular/cdk/collections';
import { CheckDuplicacyService } from '../../../services/upload/check-duplicacy/check-duplicacy.service';
import { FormsModule } from '@angular/forms';
import { UploadService } from '../../../services/upload/upload.service';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { MatMenuModule } from '@angular/material/menu';
interface FileData {
  cFilename: string;
  cStatus: string;
  file: { size: string };
  nProgress?: number;
  message?: string
}
/** Constants used to fill up our data base. */



@Component({
  selector: 'uploadtable',
  standalone: true,
  // changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [CommonModule, MatTooltipModule, IconComponent, MatCheckboxModule, FormsModule, BytesPipe, MatInputModule, MatTableModule, MatSortModule, MatPaginatorModule, MatMenuModule, MatTooltipModule],
  templateUrl: './uploadtable.component.html',
  styleUrls: ['./uploadtable.component.scss']
})
export class UploadtableComponent implements OnInit, OnChanges, AfterViewChecked {

  @Input() filterdata: uploadAppliedFilters;
  @Input() isReport: boolean = false;
  @ViewChild(MatTable) table: MatTable<Element>;
  displayedColumns: string[] = ['select', 'cFilename', 'cStatus', 'total', 'filetype', 'filesize'];
  dataSource: MatTableDataSource<fileUploadMDL>;
  @ViewChild('fileuploader', { static: true }) fileuploader: ElementRef;
  @ViewChild(MatPaginator) paginator: MatPaginator;
  @ViewChild(MatSort) sort: MatSort;
  @Input() data: fileUploadMDL[] = [];
  @Input() job: uploadMasterMDL; //uploadingFilesMDL;
  // @Input() data: fileUploadMDL[] = [];

  private docIconPath: string = environment.iconpath_doc;
  selection = new SelectionModel<FileData>(true, []);

  @Output() dataRecieved = new EventEmitter<any>();
  @Output() onFilter = new EventEmitter<any>();

  replaceableFile: fileUploadMDL;
  // isloading: boolean = true;
  public allSelected: boolean = false;
  @Output() onSelection = new EventEmitter<any>();
  isTableloaded: boolean = false;
  sortDirection: { [key: string]: 'asc' | 'desc' } = {
    name: 'asc',
    age: 'asc'
  };

  constructor(private uploadManage: UploadManagementService, private check: CheckDuplicacyService, private upld: UploadService, private tst: TostbarService, private cdr: ChangeDetectorRef) { }


  ngAfterViewChecked() {
    if (this.dataSource && this.dataSource.data.length > 0 && this.job.isLoading) {
      this.job.isLoading = false;
      // if(this.filterdata.cAction.value != null || this.filterdata.cAction.value != null || this.filterdata.cAction.value != null || this.filterdata.cAction.value == 'F'){
      // }
      this.applyFilter({ currentValue: this.filterdata });
      this.cdr.detectChanges();
    }
  }

  applyFilter(filtes) {
    this.dataSource.filter = filtes;
    this.emitFilteredDataCount();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['filterdata'] && !changes['filterdata'].firstChange) {

      this.applyFilter(changes['filterdata']);
    }

    if (changes['data'] && !changes['data'].firstChange) {
      if (this.isTableloaded) {
        this.dataSource.data = changes['data'].currentValue;
      } else {
        this.initTable();
      }
    }
  }

  ngAfterViewInit() {

    // setTimeout(() => {
    this.dataSource.paginator = this.paginator;
    this.dataSource.sort = this.sort;
    this.cdr.detectChanges();
    // }, 2000)
  }

  ngOnInit(): void {
    if (!this.isReport) {
      this.displayedColumns.push('action');
    }
    this.initTable();
  }


  initTable() {
    this.isTableloaded = true;
    this.dataSource = new MatTableDataSource(this.data);
    this.dataSource.filterPredicate = (data: any, filter: any) => {
      try {
        const { cAction, cStatus, cFormat, cSearch } = filter["currentValue"];
        // Check cAction filter
        if (cAction?.value && data.cStatus !== cAction.value) {
          return false;
        }
        // Check cStatus filter
        if (cStatus?.value && data.cStatus !== cStatus.value) {
          return false;
        }
        // Check cFormat filter
        if (cFormat?.value && !cFormat.value.includes(data.filetype)) {
          return false;
        }
        if (cSearch && data.cFilename.toLowerCase().indexOf(cSearch.toLowerCase()) === -1) {
          return false;
        }
      } catch (error) {
        console.error(error)
      }
      return true;
    };
    this.emitFilteredDataCount();
    // this.dataSource.sort = this.sort;
  }

  istextTruncated(el) {
    return el.scrollWidth > el.clientWidth;
  }

  emitFilteredDataCount() {
    const filteredCount = this.dataSource.filteredData.length;
    this.onFilter.emit(filteredCount);
  }

  bindIcon(node) {
    try {
      const fileType = node.filetype.toLowerCase();
      return `${this.docIconPath}${fileType}.svg`;
    } catch (error) {
      return `${this.docIconPath}other.svg`;
    }
  }

  pauseUploading(x) {
    x.cStatus = 'PSD';
    this.uploadManage.pauseUpload(x);
  }

  resumeUploading(x) {
    x.cStatus = 'I';
    this.uploadManage.resumeUpload(x);
  }

  replceFile(x) {
    this.replaceableFile = x;
    this.fileuploader.nativeElement.click();
  }

  async retryUpload(x: fileUploadMDL) {
    if (x.file) {
      let upldFile: fileUploadMDL = await this.check.createStructure(x.file, x.nBundledetailid, x.nUDid, x.nUPid);
      Object.assign(x, upldFile)
      x.cStatus = 'I';
      x.nProgress = 0;
      await this.uploadManage.replaceFile([upldFile], this.job.nSectionid, this.job.nUPid);
    } else {
      this.tst.openSnackBar('Failed to retry', 'E');
    }
  }

  async changeFile(e) {
    let file = e.target.files[0]
    this.replaceableFile.isReplacing = true;
    try {
      if (file) {
        let mdl: replaceMdl = {
          nUDid: this.replaceableFile.nUDid,
          cName: file.name + ' (copy)',
          cType: this.check.getFileType(file.name),
          cSize: file.size.toString()
        }
        let resOfReplace = await this.upld.replacefile(mdl);
        if (resOfReplace) {
          let upldFile: fileUploadMDL = await this.check.createStructure(file, this.replaceableFile.nBundledetailid, this.replaceableFile.nUDid, this.replaceableFile.nUPid);
          Object.assign(this.replaceableFile, upldFile)
          this.replaceableFile.cStatus = 'I';
          this.replaceableFile.nProgress = 0;
          await this.uploadManage.replaceFile([upldFile], this.job.nSectionid, this.job.nUPid);
        } else {
          this.tst.openSnackBar('Faild to replace', 'E');
        }
      }
    } catch (error) {

      this.tst.openSnackBar('Faild to replace', 'E');
    }


    delete this.replaceableFile.isReplacing;
  }

  OnAllChange() {
    // this.data.filter((a => (a.cStatus == 'C' || a.cStatus == 'F'))).map(a => a.isChecked = this.allSelected);
    this.data.map(a => a.isChecked = this.allSelected);
    let values = this.data.map(({ isChecked, nUDid }) => ([nUDid, isChecked]))
    this.onSelection.emit(values);
  }

  onSelect(row) {
    // if (this.data.filter((a => (a.cStatus == 'C' || a.cStatus == 'F'))).findIndex(a => !a.isChecked) > -1) {
    if (this.data.findIndex(a => !a.isChecked) > -1) {
      this.allSelected = false;
    } else {
      this.allSelected = true;
    }
    this.onSelection.emit([[row.nUDid, row.isChecked]]);
  }

  handleError(event: any) {
    event.target.src = 'assets/icons/doc-icons/other.svg';
  }

  sortData(column: string) {
    const data = this.dataSource.data.slice();
    const direction = this.sortDirection[column];
    data.sort((a, b) => {
      const isAsc = direction === 'asc';
      switch (column) {
        case 'name':
          return this.compare(a.cFilename, b.cFilename, isAsc);
        case 'status':
          return this.compare(a.cStatus, b.cStatus, isAsc);
        default:
          return 0;
      }
    });
  }

  compare(a: number | string, b: number | string, isAsc: boolean) {
    return (a < b ? -1 : 1) * (isAsc ? 1 : -1);
  }


  tempData() {
    try {
      return JSON.stringify(this.dataSource.data[0]);
    } catch (error) {
      return '';
    }
  }

  getOCRFiles(row) {
    this.upld.getFileData(row.nUDid, row);
  }

  getTime(row) {
    // Get the current timestamp
    const now: any = row.dStartDt ? new Date(row.dStartDt) : null;
    if (!now) {
      return '';
    }
    else {
      let endDt = row.dEndDt
      if (row.nCompleted != row.nOCRFiles) {
        endDt = new Date();
      }
      const oneDayAgo: any = endDt ? new Date(endDt) : new Date();

      // Calculate the time difference in milliseconds
      const diffMilliseconds = oneDayAgo - now;

      // Convert milliseconds to seconds
      const diffSeconds = Math.floor(diffMilliseconds / 1000);

      // Calculate total minutes and remaining seconds
      const totalMinutes = Math.floor(diffSeconds / 60);
      const totalSeconds = diffSeconds % 60;
      return `${totalMinutes} minute ${totalSeconds} second`;
    }
    // Subtract 1 day (24 hours) from now



  }
  parseToInt(value: string) {
    try {
      return parseInt(value) || 0;
    } catch (error) {
      return 0;
    }
  }
}
